/* ============================================================
   thaisound2.js — เสียงเครื่องดนตรีจริงชุดที่ 2 (อัดในห้องดนตรีไทยของชมรม)
   ระนาดเอก · ขลุ่ย · ซอด้วง · โทน–รำมะนา · ฉาบ
   ใช้: TS2.init(audioContext, outputNode) แล้วเรียก
     TS2.ranad(freq,t,v) · TS2.khlui(freq,t,dur,v) · TS2.sor(freq,t,dur,v) · TS2.thon(k,t,v) (k 0–3) · TS2.chab(k,t,v) (k 0–2)
   เสียงสูงต่ำได้จากการเลื่อนระดับเสียงตัวอย่างที่ใกล้ที่สุด
   ============================================================ */
(function(){
  'use strict';
  const SRC={"r308": "data:audio/mpeg;base64,", "r414": "data:audio/mpeg;base64,", "r558": "data:audio/mpeg;base64,", "r753": "data:audio/mpeg;base64,", "r1009": "data:audio/mpeg;base64,", "r1366": "data:audio/mpeg;base64,", "f520": "data:audio/mpeg;base64,", "f760": "data:audio/mpeg;base64,", "s678": "data:audio/mpeg;base64,", "s900": "data:audio/mpeg;base64,", "t_a": "data:audio/mpeg;base64,", "t_b": "data:audio/mpeg;base64,", "t_c": "data:audio/mpeg;base64,", "t_d": "data:audio/mpeg;base64,", "c_1": "data:audio/mpeg;base64,", "c_2": "data:audio/mpeg;base64,", "c_3": "data:audio/mpeg;base64,"};
  const PITCH={ranad:[['r308',308],['r414',414],['r558',558],['r753',753],['r1009',1009],['r1366',1366]],khlui:[['f520',520],['f760',760]],sor:[['s678',678],['s900',900]]};
  const THON=['t_a','t_b','t_c','t_d'],CHAB=['c_1','c_2','c_3'];
  let AC=null,OUT=null;const B={};
  function init(ac,out){if(AC===ac)return;AC=ac;OUT=out||ac.destination;
    Object.keys(SRC).forEach(k=>{fetch(SRC[k]).then(r=>r.arrayBuffer()).then(ab=>new Promise((res,rej)=>AC.decodeAudioData(ab,res,rej))).then(b=>{
      const d=b.getChannelData(0);let m=0;for(let i=0;i<d.length;i++)m=Math.max(m,Math.abs(d[i]));let s=0;while(s<d.length&&Math.abs(d[s])<m*.04)s++;B[k]={b,off:Math.max(0,s/b.sampleRate-.002)}}).catch(()=>{})})}
  const ready=k=>!!(k?B[k]:Object.keys(SRC).every(x=>B[x]));
  function near(list,f){let best=list[0];list.forEach(x=>{if(Math.abs(Math.log(x[1]/f))<Math.abs(Math.log(best[1]/f)))best=x});return best}
  function play(key,t,v,rate,dur,out){const s=B[key];if(!AC||!s)return false;t=Math.max(t||0,AC.currentTime);
    const n=AC.createBufferSource(),g=AC.createGain();n.buffer=s.b;n.playbackRate.value=rate||1;g.gain.setValueAtTime(v==null?1:v,t);
    if(dur){const len=(s.b.duration-s.off)/(rate||1);if(dur>len-.15){n.loop=true;n.loopStart=Math.min(s.b.duration-.3,s.off+.35);n.loopEnd=s.b.duration-.28}
      g.gain.setValueAtTime(v==null?1:v,t+Math.max(.05,dur-.08));g.gain.linearRampToValueAtTime(0,t+dur+.06)}
    n.connect(g);g.connect(out||OUT);n.start(t,s.off);if(dur)n.stop(t+dur+.1);return true}
  function pitched(kind,f,t,v,dur,out){const [k,f0]=near(PITCH[kind],f);return play(k,t,v,f/f0,dur,out)}
  window.TS2={init,ready,
    ranad:(f,t,v,out)=>pitched('ranad',f,t,v,0,out),
    khlui:(f,t,dur,v,out)=>pitched('khlui',f,t,v,dur||.6,out),
    sor:(f,t,dur,v,out)=>pitched('sor',f,t,v,dur||.5,out),
    thon:(k,t,v,out)=>play(THON[Math.max(0,Math.min(3,k|0))],t,v,1,0,out),
    chab:(k,t,v,out)=>play(CHAB[Math.max(0,Math.min(2,k|0))],t,v,1,0,out)};
})();
